const raw = items[0].json;
const fc = raw.features ? raw : (typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data);
const { uf, regiao, municipios } = $('Agregar UF').first().json;
const byCode = new Map(municipios.map(m => [String(m.geocode), m.nome]));
const registros = (fc.features || [])
  .filter(f => byCode.has(String(f.properties.codarea)))
  .map(f => ({
    geocode:  Number(f.properties.codarea),
    nome:     byCode.get(String(f.properties.codarea)),
    uf,
    regiao,
    geomJson: JSON.stringify(f.geometry),
  }));
if (registros.length === 0) throw new Error(`Sem geometria para UF ${uf}`);
return [{ json: { uf, total: registros.length, registros } }];
